// ===== Alerte paiement Stripe → Telegram =====
// Reçoit les webhooks Stripe et envoie une alerte sur la conversation Telegram.
// À faire côté utilisateur :
//  1. Dans le dashboard Stripe → Développeurs → Webhooks → Ajouter un endpoint :
//     URL de production : https://n8n.rennesdev.fr/webhook/stripe-paiement
//     Événements : checkout.session.completed, payment_intent.succeeded, invoice.payment_succeeded
//  2. Copier la "clé de signature du endpoint" (whsec_...) dans CONFIG.webhookSecret ci-dessous.
//     Tant que ce secret est vide, la signature n'est PAS vérifiée (⚠️ affiché dans le message).
const CONFIG = {
  webhookSecret: 'whsec_MASQUE', // ex: 'whsec_MASQUE' — clé de signature du webhook Stripe
};

// crypto peut être indisponible selon la config n8n → dégradation silencieuse
let crypto = null;
try { crypto = require('crypto'); } catch { /* non bloquant */ }

const rawHeaders = $json.headers || {};
const headers = {};
for (const [k, v] of Object.entries(rawHeaders)) headers[k.toLowerCase()] = v;
const sigHeader = headers['stripe-signature'];

// --- vérification de la signature Stripe (HMAC-SHA256 hexadécimal sur "<t>.<payload>") ---
// On teste le corps brut ET le corps re-sérialisé : selon la config n8n, l'ordre exact
// des octets du payload d'origine peut différer — l'un des deux doit correspondre.
const bodyRaw = typeof $json.body === 'string' ? $json.body : null;
const candidats = [JSON.stringify($json.body), ...(bodyRaw ? [bodyRaw] : [])].filter(Boolean);
let sigOk = null; // null = non vérifiée (secret manquant), true/false = résultat
if (CONFIG.webhookSecret && crypto && sigHeader) {
  const parties = Object.fromEntries(sigHeader.split(',').map((p) => p.split('=')));
  if (parties.t && parties.v1) {
    sigOk = candidats.some((c) =>
      crypto.createHmac('sha256', CONFIG.webhookSecret)
        .update(`${parties.t}.${c}`)
        .digest('hex') === parties.v1);
  } else {
    sigOk = false;
  }
}

const body = bodyRaw ? JSON.parse(bodyRaw) : ($json.body || {});
const type = body.type || 'type inconnu';

const EVENEMENTS_PAIEMENT = [
  'checkout.session.completed',
  'payment_intent.succeeded',
  'invoice.payment_succeeded',
  'charge.succeeded',
];
if (!EVENEMENTS_PAIEMENT.includes(type)) {
  return [{ json: { skip: true, text: null } }];
}

const d = body.data && body.data.object ? body.data.object : {};
let montant = '', devise = '', client = '';
if (type === 'checkout.session.completed') {
  montant = ((d.amount_total || 0) / 100).toFixed(2);
  devise = (d.currency || '').toUpperCase();
  client = (d.customer_details && d.customer_details.email) || d.customer_email || '';
} else if (type === 'invoice.payment_succeeded') {
  montant = ((d.amount_paid || 0) / 100).toFixed(2);
  devise = (d.currency || '').toUpperCase();
  client = d.customer_email || '';
} else if (type === 'payment_intent.succeeded' || type === 'charge.succeeded') {
  montant = ((d.amount || 0) / 100).toFixed(2);
  devise = (d.currency || '').toUpperCase();
  client = (d.billing_details && d.billing_details.email) || d.receipt_email || '';
}

const lignes = [`💳 Paiement Stripe reçu — ${montant} ${devise}`];
lignes.push(`Événement : ${type}`);
if (client) lignes.push(`Client : ${client}`);
lignes.push(`Reçu le ${new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' })}`);
if (sigOk === null) {
  const cause = !crypto ? 'module crypto indisponible' : (!sigHeader ? 'en-tête stripe-signature ABSENT (reçus: ' + Object.keys(rawHeaders).join(', ').slice(0, 200) + ')' : 'secret manquant dans le workflow');
  lignes.push('⚠️ Signature non vérifiée — cause : ' + cause);
}
else if (sigOk === false) lignes.push('🚨 Signature Stripe INVALIDE — webhook possiblement falsifié');

return [{ json: { text: lignes.join('\n') } }];
